COMMIT;

-- ----------------------------
-- Table structure for mdo_api
-- ----------------------------
DROP TABLE IF EXISTS `mdo_api`;
CREATE TABLE `mdo_api` (
  `id` bigint NOT NULL COMMENT 'id',
  `app_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '应用名称',
  `api_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '接口名称',
  `api_version` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '1.0' COMMENT '版本号',
  `description` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '接口描述',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '备注',
  `interface_class_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '接口类名',
  `method_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '方法名称',
  `param_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '参数信息',
  `permission` tinyint NOT NULL DEFAULT '0' COMMENT '需要授权\r\n[0-否 1-是]',
  `need_token` tinyint NOT NULL DEFAULT '0' COMMENT '需要token\r\n[0-否 1-是]',
  `common_response` tinyint NOT NULL DEFAULT '1' COMMENT '公共响应参数\r\n[0-否 1-是]',
  `reg_source` tinyint NOT NULL DEFAULT '1' COMMENT '注册来源\n[1-系统注册 2-手动注册]',
  `api_mode` tinyint NOT NULL DEFAULT '1' COMMENT '接口模式\n[1-open接口 2-Restful模式]',
  `state` tinyint NOT NULL DEFAULT '1' COMMENT '状态\r\n[1-启用 0-禁用]',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '添加时间',
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '修改时间',
  `created_by` bigint DEFAULT '0' COMMENT '创建人id',
  `updated_by` bigint DEFAULT '0' COMMENT '修改人id',
  `need_sign` tinyint NOT NULL DEFAULT '0' COMMENT '是否需要签名校验[0-否 1-是]',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_apiname_version` (`api_name`,`api_version`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='开放接口';

-- ----------------------------
-- Records of mdo_api
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for mdo_api_call_log
-- ----------------------------
DROP TABLE IF EXISTS `mdo_api_call_log`;
CREATE TABLE `mdo_api_call_log` (
  `id` bigint NOT NULL COMMENT 'ID',
  `trace_id` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '调用链id',
  `app_id` bigint NOT NULL COMMENT '所属应用',
  `app_key` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '应用秘钥',
  `app_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '应用名称',
  `request_ip` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '请求IP',
  `api_id` bigint NOT NULL COMMENT '所属接口',
  `api_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '接口名称',
  `api_version` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '版本号',
  `interface_class_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '接口类名',
  `method_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '方法名称',
  `param_info` longtext COLLATE utf8mb4_general_ci COMMENT '请求参数',
  `request_header` text COLLATE utf8mb4_general_ci COMMENT '请求头',
  `request_time` datetime(3) DEFAULT NULL COMMENT '请求时间',
  `exec_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '执行状态\n[1-执行成功,2-执行失败]',
  `response_data` longtext COLLATE utf8mb4_general_ci COMMENT '响应内容',
  `response_time` datetime(3) DEFAULT NULL COMMENT '响应时间',
  `error_msg` longtext COLLATE utf8mb4_general_ci COMMENT '异常消息',
  `created_by` bigint DEFAULT NULL COMMENT '创建人',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='调用日志';

-- ----------------------------
-- Records of mdo_api_call_log
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for mdo_app
-- ----------------------------
DROP TABLE IF EXISTS `mdo_app`;
CREATE TABLE `mdo_app` (
  `id` bigint NOT NULL COMMENT 'ID',
  `app_key` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '应用ID',
  `app_secret` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '应用秘钥',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '应用名称',
  `login_type` char(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '10' COMMENT '登录方式\n[10-单点登录 20-oauth2]',
  `type` char(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '10' COMMENT '应用类型\n[10-自建应用 20-第三方应用]',
  `state` bit(1) NOT NULL DEFAULT b'1' COMMENT '状态',
  `weight` int DEFAULT '0' COMMENT '权重',
  `intro` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '应用简介',
  `logo` bigint DEFAULT NULL COMMENT '应用图标',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `validity_start` datetime(3) DEFAULT NULL COMMENT '开始有效期',
  `validity_end` datetime(3) DEFAULT NULL COMMENT '结束有效期',
  `home_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '首页地址',
  `show` bit(1) NOT NULL DEFAULT b'1' COMMENT '是否显示\n是否在我的应用显示该应用，若设置为false，就算有权限访问，该应用也不会出现在我的应用列表',
  `is_public` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否公开\n[true=公开应用 false-私有应用]',
  `allow_ip` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '允许的IP',
  `sso_auto_login_url` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '单点登录自动登录地址',
  `sso_push` bit(1) NOT NULL DEFAULT b'1' COMMENT '是否接收消息推送',
  `sso_push_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '接收消息推送的地址',
  `sso_allow_url` varchar(5120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '允许授权的URL\n多个用逗号分割',
  `oauth2_allow_redirect_uris` varchar(5120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '允许的重定向uri',
  `oauth2_allow_grant_types` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '允许的授权类型',
  `oauth2_new_refresh` int DEFAULT '-1' COMMENT 'Refresh-Token刷新策略\r\n[0-否 1-是 -1-全局配置]',
  `oauth2_access_token_timeout` bigint DEFAULT '-1' COMMENT 'access-token有效期\r\n单位：秒\r\n[-1-全局]',
  `oauth2_refresh_token_timeout` bigint DEFAULT '-1' COMMENT 'refresh-token有效期\n单位：秒\n[-1-全局]',
  `oauth2_client_token_timeout` bigint DEFAULT '-1' COMMENT 'client-token有效期\n单位：秒\n[-1-全局]',
  `oauth2_lower_client_token_timeout` bigint DEFAULT '-1' COMMENT 'lower-client-token有效期\n单位：秒\n[-1-全局]',
  `oauth2_is_confirm` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否自动授权\r\n[1-是 0-否]',
  `apply_id` bigint DEFAULT NULL COMMENT '应用申请ID',
  `created_by` bigint DEFAULT NULL COMMENT '创建人',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_by` bigint DEFAULT NULL COMMENT '最后修改人',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '最后修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_app_key` (`app_key`) USING BTREE,
  KEY `idx_key_name` (`app_key`,`name`,`state`,`show`,`weight`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='应用';

-- ----------------------------
-- Records of mdo_app
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for mdo_app_apply
-- ----------------------------
DROP TABLE IF EXISTS `mdo_app_apply`;
CREATE TABLE `mdo_app_apply` (
  `id` bigint NOT NULL COMMENT 'id',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '名称',
  `intro` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '应用简介',
  `home_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '首页地址',
  `logo` bigint DEFAULT NULL COMMENT '图标',
  `remark` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `credential_file` bigint DEFAULT NULL COMMENT '资质文件',
  `audit_status` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '审核状态\n[0-待提交 1-待审批 2-通过 99-退回]\n',
  `audit_at` datetime(3) DEFAULT NULL COMMENT '审核时间',
  `submission_at` datetime(3) DEFAULT NULL COMMENT '提交时间',
  `review_comments` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '审核意见',
  `created_at` datetime(3) DEFAULT CURRENT_TIMESTAMP(3) COMMENT '添加时间',
  `updated_at` datetime(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '修改时间',
  `created_by` bigint DEFAULT '0' COMMENT '创建人id',
  `updated_by` bigint DEFAULT '0' COMMENT '修改人id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='应用申请';

-- ----------------------------
-- Records of mdo_app_apply
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for mdo_app_group_rel
-- ----------------------------
DROP TABLE IF EXISTS `mdo_app_group_rel`;
CREATE TABLE `mdo_app_group_rel` (
  `id` bigint NOT NULL COMMENT 'ID',
  `app_id` bigint NOT NULL COMMENT '所属应用',
  `group_id` bigint NOT NULL COMMENT '分组\nperm_group.id',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `created_by` bigint DEFAULT '0' COMMENT '创建人id',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_isvid_groupid` (`app_id`,`group_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='应用拥有的权限分组';

-- ----------------------------
-- Records of mdo_app_group_rel
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for mdo_app_keys
-- ----------------------------
DROP TABLE IF EXISTS `mdo_app_keys`;
CREATE TABLE `mdo_app_keys` (
  `id` bigint NOT NULL COMMENT 'id',
  `app_id` bigint NOT NULL DEFAULT '0' COMMENT '所属应用',
  `notify_url` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '通知地址',
  `notify_state` bit(1) DEFAULT b'0' COMMENT '通知状态',
  `notify_encryption_type` smallint DEFAULT NULL COMMENT '加密模式，[0-明文模式 1-兼容模式 2-安全模式]',
  `notify_token` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '签名校验令牌，平台和开发者共同持有，用于生成和验证 signature / msg_signature',
  `notify_encoding_aes_key` varchar(43) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'AES加解密密钥（43字符），平台和开发者共同持有。生成方式：Base64Decode(encodingAesKey + "=") 得到32字节AESKey',
  `created_at` datetime(3) DEFAULT CURRENT_TIMESTAMP(3) COMMENT '添加时间',
  `updated_at` datetime(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '修改时间',
  `created_by` bigint DEFAULT '0' COMMENT '创建人id',
  `updated_by` bigint DEFAULT '0' COMMENT '修改人id',
  `public_key_app` text COLLATE utf8mb4_general_ci COMMENT '开发者应用公钥（RSA2签名校验用）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_appid` (`app_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='应用秘钥';

-- ----------------------------
-- Records of mdo_app_keys
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for mdo_app_keys_copy1
-- ----------------------------
DROP TABLE IF EXISTS `mdo_app_keys_copy1`;
CREATE TABLE `mdo_app_keys_copy1` (
  `id` bigint NOT NULL COMMENT 'id',
  `app_id` bigint NOT NULL DEFAULT '0' COMMENT '所属应用',
  `key_format` smallint NOT NULL DEFAULT '1' COMMENT '秘钥格式\r\n[1-PKCS8(JAVA适用) 2-PKCS1(非JAVA适用)]',
  `notify_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '通知地址',
  `notify_state` bit(1) DEFAULT b'0' COMMENT '通知状态',
  `notify_encryption_type` smallint DEFAULT NULL COMMENT '加密类型\n[0-不加密 1-aes加密 2-sm4加密]',
  `public_key_app` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '应用公钥\r\n平台方用来校验开发者推送过来的数据',
  `private_key_app` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '应用私钥\r\n一般由开发者自行生成或平台协助生成\r\n用来开发者签名推送给平台的数据',
  `public_key_platform` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '平台公钥\r\n提供给开发者，用来校验平台推送给开发者的数据签名是否正确',
  `private_key_platform` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '平台私钥\r\n平台使用，用来签名推送给开发者的数据',
  `created_at` datetime(3) DEFAULT CURRENT_TIMESTAMP(3) COMMENT '添加时间',
  `updated_at` datetime(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '修改时间',
  `created_by` bigint DEFAULT '0' COMMENT '创建人id',
  `updated_by` bigint DEFAULT '0' COMMENT '修改人id',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_appid` (`app_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='应用秘钥';

-- ----------------------------
-- Records of mdo_app_keys_copy1
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for mdo_doc_content
-- ----------------------------
DROP TABLE IF EXISTS `mdo_doc_content`;
CREATE TABLE `mdo_doc_content` (
  `id` bigint NOT NULL COMMENT 'id',
  `doc_info_id` bigint NOT NULL DEFAULT '0' COMMENT '文档ID\ndoc_info.id',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '文档内容',
  `created_at` datetime(3) DEFAULT CURRENT_TIMESTAMP(3) COMMENT '添加时间',
  `updated_at` datetime(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '修改时间',
  `created_by` bigint DEFAULT '0' COMMENT '创建人id',
  `updated_by` bigint DEFAULT '0' COMMENT '修改人id',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_doc_info_id` (`doc_info_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='文档内容';

-- ----------------------------
-- Records of mdo_doc_content
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for mdo_doc_group
-- ----------------------------
DROP TABLE IF EXISTS `mdo_doc_group`;
CREATE TABLE `mdo_doc_group` (
  `id` bigint NOT NULL COMMENT 'id',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '名称',
  `token` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '令牌',
  `publish` tinyint NOT NULL DEFAULT '0' COMMENT '是否发布',
  `created_at` datetime(3) DEFAULT CURRENT_TIMESTAMP(3) COMMENT '添加时间',
  `updated_at` datetime(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '修改时间',
  `created_by` bigint DEFAULT '0' COMMENT '创建人id',
  `updated_by` bigint DEFAULT '0' COMMENT '修改人id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='文档分组';

-- ----------------------------
-- Records of mdo_doc_group
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for mdo_doc_info
-- ----------------------------
DROP TABLE IF EXISTS `mdo_doc_info`;
CREATE TABLE `mdo_doc_info` (
  `id` bigint NOT NULL COMMENT 'id',
  `doc_group_id` bigint NOT NULL COMMENT '所属分组',
  `doc_title` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '文档标题',
  `doc_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '文档编码',
  `doc_type` tinyint NOT NULL DEFAULT '1' COMMENT '文档类型\r\n[1-dubbo 2-富文本 3-Markdown]',
  `source_type` tinyint NOT NULL DEFAULT '1' COMMENT '来源类型\n[1-torna 2-自建]',
  `doc_version` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '文档版本号',
  `doc_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '文档名称',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '描述',
  `folder` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否分类',
  `publish` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '发布状态\r\n[0-未发布 1-已发布]',
  `parent_id` bigint NOT NULL COMMENT '父文档',
  `weight` int DEFAULT '0' COMMENT '排序',
  `created_at` datetime(3) DEFAULT CURRENT_TIMESTAMP(3) COMMENT '添加时间',
  `updated_at` datetime(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '修改时间',
  `created_by` bigint DEFAULT '0' COMMENT '创建人id',
  `updated_by` bigint DEFAULT '0' COMMENT '修改人id',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_doc_app_id` (`doc_group_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='文档信息';

-- ----------------------------
-- Records of mdo_doc_info
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for mdo_event_push
-- ----------------------------
DROP TABLE IF EXISTS `mdo_event_push`;
CREATE TABLE `mdo_event_push` (
  `id` bigint NOT NULL COMMENT 'ID',
  `event_trigger_id` bigint NOT NULL COMMENT '事件触发ID',
  `event_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '事件类型',
  `app_id` bigint NOT NULL COMMENT '所属应用',
  `app_key` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '应用秘钥',
  `notify_url` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '回调url',
  `notify_encryption_type` smallint DEFAULT NULL COMMENT '加密模式（冗余自 AppKeys，避免推送时再查库），[0-明文模式 1-兼容模式 2-安全模式]',
  `notify_token` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '签名校验令牌（冗余自 AppKeys）',
  `notify_encoding_aes_key` varchar(43) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'AES加解密密钥（冗余自 AppKeys）',
  `request_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '请求参数',
  `last_request_time` datetime(3) DEFAULT NULL COMMENT '最后请求时间',
  `next_request_time` datetime(3) DEFAULT NULL COMMENT '下次请求时间',
  `max_request_cnt` int DEFAULT NULL COMMENT '最大请求次数',
  `request_cnt` int DEFAULT '0' COMMENT '已请求次数',
  `exec_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '执行状态\n[0-待执行 1-执行成功 2-执行失败 3-重试结束 4-手动结束]',
  `remark` varchar(256) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT CURRENT_TIMESTAMP(3) COMMENT '修改时间',
  `created_by` bigint DEFAULT '0' COMMENT '创建人id',
  `updated_by` bigint DEFAULT '0' COMMENT '修改人id',
  PRIMARY KEY (`id`),
  KEY `idx_app_key` (`app_key`),
  KEY `idx_event_trigger_id` (`event_trigger_id`,`app_id`,`exec_status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='事件推送任务';

-- ----------------------------
-- Records of mdo_event_push
-- ----------------------------
BEGIN;
COMMIT;

